  const hud=doc.createElement('div');hud.className='m117-hud';hud.innerHTML=`<div class="m117-top"><div class="m117-brand"><span>Ｍ</span><div><b>TALLER DE OPERACIONES</b><small id="m117-mission-name"></small></div></div><nav aria-label="Menú de misión"><button id="m117-cases" aria-expanded="false">Misiones</button><button id="m117-frame">Acercar equipo</button><button id="m117-manual">Manual</button><button id="m117-pause">Pausa</button><button id="m117-home">Menú</button></nav></div><section class="m117-objective" aria-label="Objetivo actual"><div class="m117-objective-top"><span>OBJETIVO ACTUAL</span><b id="m117-step-count"></b></div><div id="m117-goal-slot"></div><div class="m117-mission-track"><i id="m117-mission-fill"></i></div><button id="m117-focus"><kbd>F</kbd> Enfocar pieza</button><div class="m118-coach"><small>QUÉ ESTÁS COMPROBANDO</small><p id="m118-why"></p><button id="m118-act"></button><div id="m118-checks" class="m118-checks"><span id="m118-check-a"></span><span id="m118-check-b"></span></div></div></section><div class="m117-bottom"><span><kbd>E</kbd> Interactuar <i>·</i> <kbd>1–4</kbd> Herramientas</span><button id="m117-actions" aria-expanded="false">Acciones disponibles</button><button id="m117-repeat">Repetir misión</button></div><output id="m117-stage-notice" class="m117-notice" aria-live="polite"></output></div>`;root.append(hud);const overview156=doc.getElementById('train156-overview');if(overview156)hud.querySelector('.m117-top').querySelector('nav').prepend(overview156);
