 choose197(){this.close();this.getBench()?.walk176?.releaseMouse182();let d=this.$('m197-choose');if(!d){d=this.doc.createElement('dialog');d.id='m197-choose';d.setAttribute('aria-label','Elegir una misión independiente');d.innerHTML='<h2>Elige una misión</h2><p>Cada práctica empieza desde cero. Puedes elegir cualquiera.</p>';for(const[id,c]of Object.entries(HAND_CASES)){const b=this.doc.createElement('button');b.type='button';b.dataset.mission197=id;b.textContent=(Object.keys(HAND_CASES).indexOf(id)+1)+' · '+c.title;b.onclick=()=>{d.close();this.restart(id);};d.append(b);}const back=this.doc.createElement('button');back.textContent='Volver al menú';back.onclick=()=>{d.close();this.leave();};d.append(back);this.doc.body.append(d);}d.onkeydown=e=>{const i=Number(e.key)-1,ids=Object.keys(HAND_CASES);if(ids[i]){e.preventDefault();d.close();this.restart(ids[i]);}};d.showModal();}
