 closeDrawers(){this.setJournal196(false);this.root.dataset.missionDrawer117='';if(this.cards)this.cards.hidden=true;if(this.actions)this.actions.hidden=true;this.$('m117-cases').setAttribute('aria-expanded','false');this.$('m117-actions').setAttribute('aria-expanded','false');}
